    /// <param name="modelName"></param>
    /// <param name="replyToId"></param>
    /// <param name="scheduleAt">RFC3339. Schedules instead of sending now — inline document only (filename + text_content), no assets, no main_upload_id. Result carries scheduled_message_id and send_at.</param>
    /// <param name="silent">Send with no sound — the push still arrives, but silently.</param>
    /// <param name="textContent">Inline path only. The document's own content, UTF-8 text.</param>
