    /// <param name="ct">Cancellation token.</param>
    public Task<ToolResult> SendDocumentAsync(string conversationId, IReadOnlyList<string>? assetPaths = null, IReadOnlyList<string>? assetUploadIds = null, IReadOnlyList<System.Text.Json.Nodes.JsonNode>? assets = null, string? caption = null, string? clientMessageId = null, string? filename = null, string? mainUploadId = null, string? modelName = null, string? replyToId = null, string? scheduleAt = null, bool? silent = null, string? textContent = null, string? topicId = null, CancellationToken ct = default)
    {
