        Put(a, "model_name", modelName);
        Put(a, "reply_to_id", replyToId);
        Put(a, "schedule_at", scheduleAt);
        Put(a, "silent", silent);
        Put(a, "text_content", textContent);
        Put(a, "topic_id", topicId);
        return CallToolAsync("send_document", a, true, ct);
